class AccountScreen extends StatelessWidget { const AccountScreen({super.key}); @override Widget build(BuildContext context){final app=context.watch<AppController>(); return Scaffold(appBar:AppBar(title:const Text('حسابي والإعدادات'),actions:[IconButton(onPressed:()=>app.refreshAll(),icon:const Icon(Icons.refresh))]),body:ListView(padding:const EdgeInsets.all(12),children:[PageCard(child:Column(children:[const CircleAvatar(radius:28,backgroundColor:AppColors.burgundy,child:Icon(Icons.person,color:Colors.white,size:30)),const SizedBox(height:8),Text(app.user?.name??'',style:const TextStyle(fontWeight:FontWeight.w900,fontSize:16)),Text(app.user?.phone??'',style:const TextStyle(color:Colors.black54)),Text(app.user?.governorate??'',style:const TextStyle(fontSize:11,color:Colors.black45))])),const SizedBox(height:10),PageCard(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('المحفظة',textAlign:TextAlign.right,style:TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:8),Text('${app.walletBalance.toStringAsFixed(2)} ر.ي',textAlign:TextAlign.center,style:const TextStyle(fontSize:24,fontWeight:FontWeight.w900,color:AppColors.burgundy)),const SizedBox(height:8),Text('الحركات: ${app.operations.length}  •  الطلبات: ${app.orders.length}',textAlign:TextAlign.center,style:const TextStyle(fontSize:11,color:Colors.black54))])),const SizedBox(height:10),SectionHeader(title:'عناوين التوصيل',color:AppColors.blue),const SizedBox(height:6),if(app.addresses.isEmpty)const PageCard(child:Text('لا توجد عناوين محفوظة.',textAlign:TextAlign.center)) else ...app.addresses.map((a)=>Padding(padding:const EdgeInsets.only(bottom:6),child:PageCard(child:Row(children:[const Icon(Icons.location_on_outlined,color:AppColors.blue),const SizedBox(width:7),Expanded(child:Text('${a['label']??a['name']??'عنوان'}\n${a['address']??a['details']??a['city']??''}',textAlign:TextAlign.right,style:const TextStyle(fontSize:11,fontWeight:FontWeight.w700)))])))),const SizedBox(height:14),OutlinedButton.icon(onPressed:()=>showDialog(context:context,builder:(_)=>const _AddressDialog()),icon:const Icon(Icons.add_location_alt_outlined),label:const Text('إضافة عنوان')),const SizedBox(height:10),FilledButton.icon(style:FilledButton.styleFrom(backgroundColor:Colors.red.shade600),onPressed:()=>showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('تسجيل الخروج'),content:const Text('هل تريد تسجيل الخروج من الحساب؟'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('إلغاء')),FilledButton(onPressed:(){Navigator.pop(context);app.logout();},child:const Text('خروج'))])),icon:const Icon(Icons.logout),label:const Text('تسجيل الخروج'))]));}}
class _AddressDialog extends StatefulWidget{const _AddressDialog();@override State<_AddressDialog> createState()=>_AddressDialogState();}
class _AddressDialogState extends State<_AddressDialog>{final label=TextEditingController();final address=TextEditingController();final city=TextEditingController();@override void dispose(){label.dispose();address.dispose();city.dispose();super.dispose();}@override Widget build(BuildContext context)=>AlertDialog(title:const Text('إضافة عنوان'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:label,decoration:const InputDecoration(labelText:'اسم العنوان')),TextField(controller:address,decoration:const InputDecoration(labelText:'العنوان')),TextField(controller:city,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'رقم المدينة city_id'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('إلغاء')),FilledButton(onPressed:()async{try{await context.read<AppController>().api.createAddress({'label':label.text,'address':address.text,'city_id':int.tryParse(city.text)});await context.read<AppController>().refreshAll();if(context.mounted)Navigator.pop(context);}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}},child:const Text('حفظ'))]);}
